import pathlib,subprocess,re,json
repo=pathlib.Path('/home/bamedeo/kin-wt/build-time');base='3f88125';out=pathlib.Path('/mnt/windows/Users/amedeo/Desktop/gamedev/kin-renderer-interface-bench')
def original(path):return subprocess.check_output(['git','show',base+':'+path],cwd=repo,text=True)
def normalized(s):return re.sub(r'\s+','',re.sub(r'^\s*#include[^\n]*\n','',s,flags=re.M))
header='engine/include/kin/renderer/renderer2d.hpp';old_header=original(header)
forwarders=[('IRendererBackend3D*','renderer_3d','','', 'return _backend->renderer_3d();'),('void','set_overdraw_view','bool enabled','','_backend->set_overdraw_view(enabled);'),('std::string','pipeline_record','',' const', 'return _backend->pipeline_record();'),('void','prewarm_pipelines','std::string_view record','','_backend->prewarm_pipelines(record);')]
paths=subprocess.check_output(['git','diff','--name-only',base,'--','engine','tests'],cwd=repo,text=True).splitlines();checked=[]
for path in paths:
 if not path.endswith(('.hpp','.cpp')):continue
 old=original(path);new=(repo/path).read_text()
 if path.endswith('/backend.hpp'):
  start=old.index('// How Renderer2D::draw_distance_field');end=old.index('class IRenderer2DBackend {',start);block=old[start:end]
  expected='#pragma once\n\n#include <kin/core/types.hpp>\n#include <kin/renderer/color.hpp>\n#include <kin/renderer/gpu_memory_stats.hpp>\n\n#include <span>\n#include <string>\n\nnamespace kin {\n\nclass DataBuffer;\nclass Texture;\nstruct ShaderParams;\n\n'+block+'} // namespace kin\n'
  assert (repo/'engine/include/kin/renderer/backend_types.hpp').read_text()==expected
  old=old[:start]+old[end:]
 if path==header:
  for ret,name,args,qual,body in forwarders:
   definition=f'{ret} {name}({args}){qual} {{ {body} }}';declaration=f'{ret} {name}({args}){qual};'
   assert definition in old and declaration in new;new=new.replace(declaration,definition,1)
  for declaration in ['class Window;','class IRenderer2DBackend;','class IRendererBackend3D;','class JobSystem;','struct CompressedImage;']:
   assert new.count(declaration)==old.count(declaration)+1;new=new.replace(declaration,'',1)
 if path=='engine/src/renderer/renderer2d.cpp':
  for ret,name,args,qual,body in forwarders:
   definition=f'{ret} Renderer2D::{name}({args}){qual} {{\n    {body}\n}}\n\n'
   assert definition in new;new=new.replace(definition,'',1)
 assert normalized(old)==normalized(new),path
 checked.append(path)
result={'base_commit':subprocess.check_output(['git','rev-parse',base],cwd=repo,text=True).strip(),'existing_cpp_files_checked':checked,'existing_fields_signatures_and_bodies_preserved':True,'five_backend_value_types_moved_byte_for_byte':True,'four_forwarding_method_bodies_preserved_out_of_line':True};(out/'mechanical-check.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))

